/**
 * Telegram Node - Version 1
 * Discriminator: resource=message, operation=sendRichMessage
 */


interface Credentials {
  telegramApi: CredentialReference;
}

/** Send a richly formatted message with headings, lists, tables, media and more */
export type TelegramV1MessageSendRichMessageParams = {
  resource: 'message';
  operation: 'sendRichMessage';
/**
 * Unique identifier for the target chat or username, To find your chat ID ask @get_id_bot
 */
    chatId: string | Expression<string>;
/**
 * Which formatting syntax the rich message content uses
 * @default html
 */
    richFormat?: 'markdown' | 'html' | Expression<string>;
/**
 * Content of the rich message, written in the selected Markdown or HTML syntax. Supports headings, lists, tables, block quotes, media, collapsible blocks and more.
 * @hint Limits: up to 32768 characters, 500 blocks and 50 media attachments
 */
    richMessageText: string | Expression<string>;
/**
 * Additional interface options
 * @default none
 */
    replyMarkup?: 'forceReply' | 'inlineKeyboard' | 'none' | 'replyKeyboard' | 'replyKeyboardRemove' | Expression<string>;
/**
 * Force Reply
 * @displayOptions.show { replyMarkup: ["forceReply"] }
 * @default {}
 */
    forceReply?: {
    /** Whether to show reply interface to the user, as if they manually selected the bot‘s message and tapped ’Reply
     * @default false
     */
    force_reply?: boolean | Expression<boolean>;
    /** Whether to force reply from specific users only
     * @default false
     */
    selective?: boolean | Expression<boolean>;
  };
/**
 * Adds an inline keyboard that appears right next to the message it belongs to
 * @displayOptions.show { replyMarkup: ["inlineKeyboard"] }
 * @default {}
 */
    inlineKeyboard?: {
        /** Rows
     */
    rows?: Array<{
      /** The value to set
       * @default {}
       */
      row?: {
        /** Buttons
     */
    buttons?: Array<{
      /** Label text on the button
       */
      text?: string | Expression<string>;
      /** Additional Fields
       * @default {}
       */
      additionalFields?: {
    /** Data to be sent in a callback query to the bot when button is pressed, 1-64 bytes
     */
    callback_data?: string | Expression<string>;
    /** Whether to send a Pay button
     * @default false
     */
    pay?: boolean | Expression<boolean>;
    /** If set, pressing the button will insert the bot‘s username and the specified inline query in the current chat's input field.Can be empty, in which case only the bot’s username will be inserted
     */
    switch_inline_query_current_chat?: string | Expression<string>;
    /** If set, pressing the button will prompt the user to select one of their chats, open that chat and insert the bot‘s username and the specified inline query in the input field. Can be empty, in which case just the bot’s username will be inserted.
     */
    switch_inline_query?: string | Expression<string>;
    /** HTTP or tg:// URL to be opened when button is pressed
     */
    url?: string | Expression<string>;
    /** Launch the Telegram Web App
     * @default {}
     */
    web_app?: {
    /** An HTTPS URL of a Web App to be opened
     */
    url?: string | Expression<string>;
  };
  };
    }>;
  };
    }>;
  };
/**
 * Adds a custom keyboard with reply options
 * @displayOptions.show { replyMarkup: ["replyKeyboard"] }
 * @default {}
 */
    replyKeyboard?: {
        /** Rows
     */
    rows?: Array<{
      /** The value to set
       * @default {}
       */
      row?: {
        /** Buttons
     */
    buttons?: Array<{
      /** Text of the button. If none of the optional fields are used, it will be sent as a message when the button is pressed.
       */
      text?: string | Expression<string>;
      /** Additional Fields
       * @default {}
       */
      additionalFields?: {
    /** Whether the user's phone number will be sent as a contact when the button is pressed.Available in private chats only
     * @default false
     */
    request_contact?: boolean | Expression<boolean>;
    /** Whether the user's request_location
     * @default false
     */
    request_location?: boolean | Expression<boolean>;
    /** Launch the Telegram Web App
     * @default {}
     */
    web_app?: {
    /** An HTTPS URL of a Web App to be opened
     */
    url?: string | Expression<string>;
  };
  };
    }>;
  };
    }>;
  };
/**
 * Reply Keyboard Options
 * @displayOptions.show { replyMarkup: ["replyKeyboard"] }
 * @default {}
 */
    replyKeyboardOptions?: {
    /** Whether to request clients to resize the keyboard vertically for optimal fit
     * @default false
     */
    resize_keyboard?: boolean | Expression<boolean>;
    /** Whether to request clients to hide the keyboard as soon as it's been used
     * @default false
     */
    one_time_keyboard?: boolean | Expression<boolean>;
    /** Whether to show the keyboard to specific users only
     * @default false
     */
    selective?: boolean | Expression<boolean>;
  };
/**
 * Reply Keyboard Remove
 * @displayOptions.show { replyMarkup: ["replyKeyboardRemove"] }
 * @default {}
 */
    replyKeyboardRemove?: {
    /** Whether to request clients to remove the custom keyboard
     * @default false
     */
    remove_keyboard?: boolean | Expression<boolean>;
    /** Whether to force reply from specific users only
     * @default false
     */
    selective?: boolean | Expression<boolean>;
  };
/**
 * Additional Fields
 * @default {}
 */
    additionalFields?: {
    /** Whether to send the message silently. Users will receive a notification with no sound.
     * @default false
     */
    disable_notification?: boolean | Expression<boolean>;
    /** Unique identifier of the message effect to be added to the message; for private chats only
     */
    message_effect_id?: string | Expression<string>;
    /** The unique identifier of the forum topic
     * @default 0
     */
    message_thread_id?: number | Expression<number>;
    /** Whether to protect the contents of the sent message from forwarding and saving
     * @default false
     */
    protect_content?: boolean | Expression<boolean>;
    /** Whether the rich message must be shown right-to-left
     * @default false
     */
    is_rtl?: boolean | Expression<boolean>;
    /** Whether to skip automatic detection of entities such as URLs, emails, mentions, hashtags and phone numbers
     * @default false
     */
    skip_entity_detection?: boolean | Expression<boolean>;
  };
};

export type TelegramV1MessageSendRichMessageNode = {
  type: 'n8n-nodes-base.telegram';
  version: 1;
  config: NodeConfig<TelegramV1MessageSendRichMessageParams> & { credentials?: Credentials };
};